3	import (
4		"fmt"
5		"regexp"
6		"strconv"
7		"strings"
8	)
9	
10	// mlScale 是数量的定点刻度：所有数量以千分之一毫升为单位的整数保存。
11	// 合法输入最多三位小数，因此登记、分装扣减与汇总都是精确的整数运算，
12	// 不会因浮点舍入多出或丢失样品。
13	const mlScale int64 = 1000
14	
15	// 数量只接受整数部分至少一位、小数部分零到三位的十进制写法，不接受符号、
16	// 小数点开头或科学计数法。调用方仍需单独判断数值必须大于零。
17	var quantityPattern = regexp.MustCompile(`^\d+(?:\.\d{1,3})?$`)
18	
19	// parseQuantity 把三位小数量（单位：毫升）解析为千分之一毫升的整数。
20	func parseQuantity(raw string) (int64, error) {
21		s := strings.TrimSpace(raw)
22		if !quantityPattern.MatchString(s) {
23			return 0, fmt.Errorf("%w: 数量 %q 必须是大于零且最多三位小数的十进制毫升数", ErrInvalid, raw)
24		}
25	
26		wholePart := s
27		fracPart := ""
28		if dot := strings.IndexByte(s, '.'); dot >= 0 {
29			wholePart = s[:dot]
30			fracPart = s[dot+1:]
31		}
32	
33		whole, err := strconv.ParseInt(wholePart, 10, 64)
34		if err != nil {
35			return 0, fmt.Errorf("%w: 数量 %q 超出可表示范围", ErrInvalid, raw)
36		}
37		for len(fracPart) < 3 {
38			fracPart += "0"
39		}
40		frac, err := strconv.ParseInt(fracPart, 10, 64)
41		if err != nil {
42			return 0, fmt.Errorf("%w: 数量 %q 超出可表示范围", ErrInvalid, raw)
43		}
44	
45		units := whole*mlScale + frac
46		if units <= 0 {
47			return 0, fmt.Errorf("%w: 数量 %q 必须大于零", ErrInvalid, raw)
48		}
49		if units/mlScale != whole {
50			return 0, fmt.Errorf("%w: 数量 %q 超出可表示范围", ErrInvalid, raw)
51		}
52		return units, nil
53	}
54	
55	// formatUnits 把内部整数数量统一渲染为三位小数的毫升字符串。
56	func formatUnits(units int64) string {
57		if units < 0 {
58			return "-" + formatUnits(-units)
59		}
60		return fmt.Sprintf("%d.%03d", units/mlScale, units%mlScale)
61	}
62	
63	// trimRequired 去掉首尾空白，并要求结果非空。
64	func trimRequired(field, raw string) (string, error) {
65		v := strings.TrimSpace(raw)
66		if v == "" {
67			return "", fmt.Errorf("%w: %s去掉首尾空白后不能为空", ErrInvalid, field)
68		}
69		return v, nil
70	}
