272		if _, err := s.Confirm(ConfirmInput{"TR-1", "王五", "实验室B", rAt}); !errors.Is(err, ErrConflict) {
273			t.Fatalf("非指定接收人应拒绝, got %v", err)
274		}
275		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "实验室A", rAt}); !errors.Is(err, ErrConflict) {
276			t.Fatalf("错误地点应拒绝, got %v", err)
277		}
278		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "实验室B", hAt.Add(-time.Second)}); !errors.Is(err, ErrInvalid) {
279			t.Fatalf("接收早于交出应拒绝, got %v", err)
280		}
281		// 拒绝后仍处于待确认、位置不变。
282		got, _ = s.GetSample("P")
283		if got.Holder != "张三" || got.PendingTransfer == nil {
284			t.Fatalf("被拒绝的接收改动了状态: %+v", got)
285		}
286	
287		// 接收时间恰好等于交出时间应允许（不能早于）。
288		done, err := s.Confirm(ConfirmInput{"TR-1", "李四", "实验室B", hAt})
289		if err != nil {
290			t.Fatalf("确认: %v", err)
291		}
292		if !done.Confirmed || done.ReceivedAt == nil || !done.ReceivedAt.Equal(hAt) {
293			t.Fatalf("确认视图错误: %+v", done)
294		}
295		got, _ = s.GetSample("P")
296		if got.Holder != "李四" || got.Location != "实验室B" || got.PendingTransfer != nil {
297			t.Fatalf("确认后应改变持有人地点并结束待确认: %+v", got)
298		}
299		kinds := []string{}
300		for _, h := range got.History {
301			kinds = append(kinds, h.Kind)
302		}
303		wantKinds := []string{"register", "transfer-out", "transfer-in"}
304		if len(kinds) != 3 {
305			t.Fatalf("历史顺序错误: %v", kinds)
306		}
307		for i := range wantKinds {
308			if kinds[i] != wantKinds[i] {
309				t.Fatalf("历史顺序错误: %v", kinds)
310			}
311		}
