360	func TestTransferIdempotency(t *testing.T) {
361		s, _ := fixedStore(t)
362		mustRegister(t, s, "P", "2.000", "张三", "A")
363		mustRegister(t, s, "Q", "2.000", "张三", "A")
364		at := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
365	
366		in := HandoverInput{
367			TransferID: "TR-1", SampleID: "P",
368			FromHolder: "张三", FromLocation: "A",
369			ToHolder: "李四", ToLocation: "B", HandedOverAt: at,
370		}
371		first, err := s.Handover(in)
372		if err != nil {
373			t.Fatal(err)
374		}
375		// 待确认状态下重复提交相同请求：返回原交接。
376		again, err := s.Handover(in)
377		if err != nil {
378			t.Fatalf("重复提交不应报错: %v", err)
379		}
380		if again != first && again.TransferID != first.TransferID {
381			t.Fatalf("重复提交应返回原交接")
382		}
383		if len(s.data.Transfers) != 1 {
384			t.Fatalf("重复提交不得新增交接记录")
385		}
386	
387		// 沿用编号改内容 → 拒绝（待确认期间）。
388		mutated := in
389		mutated.ToLocation = "C"
390		if _, err := s.Handover(mutated); !errors.Is(err, ErrConflict) {
391			t.Fatalf("同编号不同内容应拒绝, got %v", err)
392		}
393		mutated = in
394		mutated.SampleID = "Q"
395		if _, err := s.Handover(mutated); !errors.Is(err, ErrConflict) {
396			t.Fatalf("同编号换样品应拒绝, got %v", err)
397		}
398		mutated = in
399		mutated.HandedOverAt = at.Add(time.Minute)
400		if _, err := s.Handover(mutated); !errors.Is(err, ErrConflict) {
401			t.Fatalf("同编号改时间应拒绝, got %v", err)
402		}
403	
404		// 确认后：重复相同接收信息返回原结果，不增加转手记录。
405		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "B", at.Add(time.Hour)}); err != nil {
406			t.Fatal(err)
407		}
408		sampleAfter, _ := s.GetSample("P")
409		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "B", at.Add(time.Hour)}); err != nil {
410			t.Fatalf("已确认交接重复相同接收应返回原结果: %v", err)
411		}
412		if _, err := s.Handover(in); err != nil {
413			t.Fatalf("已确认交接重复相同交出请求应返回原交接: %v", err)
414		}
415		sampleSame, _ := s.GetSample("P")
416		if len(sampleSame.History) != len(sampleAfter.History) {
417			t.Fatalf("幂等重复不得增加转手/历史记录: before=%d after=%d",
418				len(sampleAfter.History), len(sampleSame.History))
419		}
420	
421		// 已确认后接收信息不同 → 拒绝。
422		if _, err := s.Confirm(ConfirmInput{"TR-1", "李四", "B", at.Add(2 * time.Hour)}); !errors.Is(err, ErrConflict) {
423			t.Fatalf("不同接收时间应拒绝, got %v", err)
424		}
425		if _, err := s.Confirm(ConfirmInput{"TR-1", "张三", "B", at.Add(time.Hour)}); !errors.Is(err, ErrConflict) {
426			t.Fatalf("不同接收人应拒绝, got %v", err)
427		}
428	}
429	
430	func TestParentChildTransfersIndependent(t *testing.T) {
431		s, _ := fixedStore(t)
432		mustRegister(t, s, "P", "10.000", "张三", "A")
433		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
434			{ID: "C", Qty: "4.000"},
435		}}); err != nil {
