458			TransferID: "TC", SampleID: "C",
459			FromHolder: "张三", FromLocation: "A",
460			ToHolder: "王五", ToLocation: "C", HandedOverAt: at.Add(2 * time.Hour),
461		}); err != nil {
462			t.Fatalf("子样应能独立交接: %v", err)
463		}
464	}
