	}

	// 对同一来源接着分出最后 0.001：剩余量准确变为 0.000，初始量仍为登记值。
	parent, err = s.Split(SplitInput{ParentID: parentID, Parts: []SplitPart{
		{ID: lastID, Qty: "0.001"},
